function drawFlower(x,y,c){line(x,y,x,y+11,'#5c8a4e',2);ellipse(x,y,4,4,c);ellipse(x-4,y,3,3,c);ellipse(x+4,y,3,3,c);ellipse(x,y-4,3,3,c);ellipse(x,y+4,3,3,c);ellipse(x,y,2,2,'#e7b44e')}
function drawHouse(x,y){
 // shadow and cottage body
 ellipse(x+94,y+112,114,17,'#55774955');roundRect(x+12,y+36,166,96,7,'#f1dfb8');
 ctx.fillStyle='#efe4c8';ctx.fillRect(x+23,y+46,145,78);ctx.fillStyle='#d7c299';ctx.fillRect(x+14,y+122,164,9);
 // roof
 ctx.fillStyle='#a95e48';ctx.beginPath();ctx.moveTo(x,y+48);ctx.lineTo(x+89,y-10);ctx.lineTo(x+190,y+48);ctx.lineTo(x+180,y+55);ctx.lineTo(x+88,y+0);ctx.lineTo(x+9,y+57);ctx.fill();
 ctx.fillStyle='#c77757';ctx.beginPath();ctx.moveTo(x+11,y+49);ctx.lineTo(x+88,y-2);ctx.lineTo(x+88,y+44);ctx.lineTo(x+31,y+69);ctx.lineTo(x+14,y+61);ctx.fill();
 // roof shingles
 for(let i=0;i<5;i++)line(x+18+i*13,y+48-i*8,x+54+i*13,y+55-i*8,'#da9670',2);
 // windows
 for(const wx of [x+37,x+126]){roundRect(wx,y+62,29,30,4,'#a9cfce','#fff6db');line(wx+14,y+64,wx+14,y+91,'#f3ead1',3);line(wx+2,y+77,wx+27,y+77,'#f3ead1',3)}
 // door and porch
 roundRect(x+83,y+75,29,56,4,'#8a6547');roundRect(x+88,y+80,19,51,3,'#9b7955');ellipse(x+103,y+106,2,2,'#efca72');
 line(x+76,y+132,x+120,y+132,'#987450',4);line(x+80,y+132,x+80,y+145,'#987450',3);line(x+116,y+132,x+116,y+145,'#987450',3);
 // chimney
 roundRect(x+142,y+4,17,34,2,'#a95e48');line(x+140,y+5,x+161,y+5,'#854b40',4);
 // entry planter
 roundRect(x+48,y+112,22,10,3,'#b67a4d');for(let i=0;i<3;i++){line(x+52+i*7,y+112,x+50+i*8,y+103,'#55844e',2);ellipse(x+49+i*8,y+102,4,3,'#80a95e')}
}
function drawShed(x,y){ellipse(x+40,y+58,51,9,'#55774955');roundRect(x,y+20,80,40,4,'#d7c397');ctx.fillStyle='#bc7950';ctx.beginPath();ctx.moveTo(x-7,y+23);ctx.lineTo(x+40,y-5);ctx.lineTo(x+87,y+23);ctx.fill();roundRect(x+29,y+31,23,29,3,'#8b6348');line(x+40,y+32,x+40,y+58,'#b7936d',2);line(x+25,y+61,x+56,y+61,'#926d49',3)}
function drawSign(x,y){line(x+22,y+21,x+22,y+65,'#84603f',5);roundRect(x,y+3,48,29,5,'#9d754a','#704e37');ctx.fillStyle='#fff0c8';ctx.font='bold 11px DM Sans,sans-serif';ctx.textAlign='center';ctx.fillText('FARM',x+24,y+22);line(x+10,y+13,x+34,y+13,'#c89e68',1)}
function drawPond(x,y){ellipse(x,y+31,65,41,'#719c5d');ellipse(x,y+26,57,35,'#83c2c1');ellipse(x-12,y+16,20,6,'#a5d7cf');ellipse(x+20,y+33,17,5,'#a5d7cf');ellipse(x+41,y+8,4,3,'#eff0b8');ellipse(x+48,y+12,3,2,'#eff0b8');line(x-50,y+30,x-41,y+24,'#dce8ae',2)}
function drawCrop(cx,cy,p){
 const info=crops[p.crop],stage=Math.min(1,p.age/info.days),height=13+stage*18,leaf=6+stage*5;
 // stem
 line(cx,cy+17,cx,cy+17-height,'#426f42',3);
 for(let side of [-1,1]){const yy=cy+12-height*.48;ctx.save();ctx.translate(cx,yy);ctx.rotate(side*.38);ellipse(side*leaf*.6,0,leaf,4,'#6caa58');ctx.restore();const yy2=cy+13-height*.78;ctx.save();ctx.translate(cx,yy2);ctx.rotate(-side*.48);ellipse(side*leaf*.52,0,leaf*.8,3.8,'#82b966');ctx.restore()}
 if(stage>.5){if(p.crop==='sunflower'){ellipse(cx,cy+17-height,9,9,'#e6b849');ellipse(cx,cy+17-height,4,4,'#6d5336');for(let a=0;a<8;a++){let ang=a*Math.PI/4;ellipse(cx+Math.cos(ang)*9,cy+17-height+Math.sin(ang)*9,3,4,'#f4cf67')}}else if(p.crop==='tomato'||p.crop==='berry'){ellipse(cx-5,cy+13-height*.65,5,5,info.color);ellipse(cx+6,cy+16-height*.39,5,5,info.color);ellipse(cx,cy+12-height*.92,4.5,4.5,info.color)}else if(stage>.85){ctx.fillStyle='#e99c45';ctx.beginPath();ctx.moveTo(cx-4,cy+7-height*.72);ctx.lineTo(cx+4,cy+7-height*.72);ctx.lineTo(cx,cy+18-height*.34);ctx.closePath();ctx.fill()}}
 if(p.ready){ellipse(cx,cy+19,13,5,'#e8c974');}
}
function plotAt(px,py){const r=canvas.getBoundingClientRect(),x=(px-r.left)/r.width*W,y=(py-r.top)/r.height*H,col=Math.floor((x-OX)/(TILE+GAP)),row=Math.floor((y-OY)/(TILE+GAP));if(col<0||col>=COLS||row<0||row>=ROWS)return -1;const tx=OX+col*(TILE+GAP),ty=OY+row*(TILE+GAP);return x<=tx+TILE&&y<=ty+TILE?row*COLS+col:-1}
function addSparkles(i,color='#fff0a1'){const x=OX+(i%COLS)*(TILE+GAP)+TILE/2,y=OY+Math.floor(i/COLS)*(TILE+GAP)+TILE/2;for(let n=0;n<4;n++)particles.push({x:x+(Math.random()-.5)*25,y:y+(Math.random()-.5)*12,life:28+Math.random()*12,color})}
function doPlot(i){if(i<0)return;const p=game.plots[i];if(game.tool==='plant'){
 if(p.crop){toast('That plot is already growing something');return}if((game.inventory[game.selected]||0)<1){toast('No '+crops[game.selected].name.toLowerCase()+' seeds left — visit the shop!');return}
 p.crop=game.selected;p.age=0;p.watered=false;p.ready=false;game.inventory[game.selected]--;game.daily.planted++;addSparkles(i,'#d9efaa');toast(crops[game.selected].name+' seed planted! Give it a drink.');beep(540);
 }else if(game.tool==='water'){
 if(!p.crop){toast('Nothing growing here to water');return}if(p.ready){toast('This one is ready to harvest!');return}if(p.watered){toast('Already watered today 💧');return}p.watered=true;game.daily.watered++;addSparkles(i,'#aeeaf1');toast('A refreshing drink for your crop');beep(680);
 }else if(game.tool==='harvest'){
 if(!p.crop){toast('Plant something here first');return}if(!p.ready){toast('Not quite ripe yet — keep watering!');return}const crop=crops[p.crop];game.money+=crop.sell;game.daily.harvested++;toast('Lovely '+crop.name.toLowerCase()+'! +'+crop.sell+' coins');addSparkles(i,'#ffe899');p.crop=null;p.age=0;p.ready=false;p.watered=false;beep(820);
 }else if(game.tool==='clear'){
 if(!p.crop){toast('This plot is already clear');return}p.crop=null;p.age=0;p.ready=false;p.watered=false;toast('Plot cleared');beep(310)
 }updateAll();save();draw()}

