function renderUI(){
 document.getElementById('dayLabel').textContent='Day '+game.day;
 document.getElementById('seasonLabel').textContent=['Spring','Summer','Autumn','Winter'][game.season%4];
 document.getElementById('weatherIcon').textContent=weatherTypes[game.weather].icon;document.getElementById('weatherLabel').textContent=weatherTypes[game.weather].name;
 document.getElementById('moneyLabel').textContent=game.money;
 document.getElementById('seedList').innerHTML=Object.entries(crops).map(([id,c])=>`<div class="seed-row ${game.selected===id?'selected':''}" data-seed="${id}"><div class="seed-icon">${c.emoji}</div><div><div class="seed-name">${c.name}</div><div class="seed-meta">${c.days} days · sells ${c.sell} 🪙</div></div><div class="seed-count">×${game.inventory[id]||0}</div></div>`).join('');
 document.getElementById('quests').innerHTML=game.quests.map(q=>{const n=Math.min(game.daily[q.type]||0,q.target);return `<div class="quest"><div class="quest-head"><span>${q.claimed?'✓ ':''}${q.title}</span><span>${n}/${q.target}</span></div><div class="quest-desc">${q.desc}</div><div class="progress"><i style="width:${100*n/q.target}%"></i></div><div class="reward">${q.claimed?'BONUS COLLECTED':'🪙 '+q.reward+' bonus coins'}</div></div>`}).join('');
